    {
      "name": "Polynomial.smeval_comp",
      "module_name": "Mathlib.Algebra.Polynomial.Smeval",
      "kind": "theorem",
      "type": "∀ (R : Type u_1) [inst : Semiring R] (p q : Polynomial R) {S : Type u_2} [inst_1 : NonAssocSemiring S]\n  [inst_2 : Module R S] [inst_3 : Pow S ℕ] (x : S) [NatPowAssoc S] [IsScalarTower R S S] [SMulCommClass R S S],\n  (p.comp q).smeval x = p.smeval (q.smeval x)"
    },
    {
      "name": "Polynomial.comp",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Defs",
      "kind": "definition",
      "type": "{R : Type u} → [inst : Semiring R] → Polynomial R → Polynomial R → Polynomial R"
    },
    {
      "name": "Polynomial.eval_comp",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Defs",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] {p q : Polynomial R} {x : R},\n  Polynomial.eval x (p.comp q) = Polynomial.eval (Polynomial.eval x q) p"
    },
    {
      "name": "MvPolynomial.aeval_comp_bind₁",
      "module_name": "Mathlib.Algebra.MvPolynomial.Monad",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_3} {S : Type u_4} [inst : CommSemiring R] [inst_1 : CommSemiring S]\n  [inst_2 : Algebra R S] (f : τ → S) (g : σ → MvPolynomial τ R),\n  (MvPolynomial.aeval f).comp (MvPolynomial.bind₁ g) = MvPolynomial.aeval fun i => (MvPolynomial.aeval f) (g i)"
    },
    {
      "name": "Polynomial.eval₂_comp'",
      "module_name": "Mathlib.Algebra.Polynomial.Eval.Algebra",
      "kind": "theorem",
      "type": "∀ {R : Type u} {S : Type v} [inst : CommSemiring R] [inst_1 : Semiring S] [inst_2 : Algebra R S] (x : S)\n  (p q : Polynomial R),\n  Polynomial.eval₂ (algebraMap R S) x (p.comp q) =\n    Polynomial.eval₂ (algebraMap R S) (Polynomial.eval₂ (algebraMap R S) x q) p"
    }
  ]
}
